package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec

// helpers for numeric field storage
func pow10Int(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func pow10Dec(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

// store unsigned PIC 9(intDigits)V99 etc. truncate toward zero and keep low-order digits
func storePic(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	t := d.Truncate(int32(scale))
	// keep low order digits: modulo 10^(intDigits+scale) on scaled integer
	modulus := pow10Dec(intDigits + scale)
	scaled := t.Shift(int32(scale))
	// work with absolute value (unsigned fields)
	neg := scaled.IsNegative()
	abs := scaled.Abs()
	if abs.GreaterOrEqual(modulus) {
		abs = abs.Mod(modulus)
		scaled = abs
		if neg {
			scaled = scaled.Neg()
		}
	} else {
		scaled = t.Shift(int32(scale))
	}
	return scaled.Shift(int32(-scale)).Truncate(int32(scale))
}

func storeInt3(v int64) int64 {
	return v % 1000
}

// formatting of numeric-edited pictures containing Z , 9 . ,
func formatEdited(val decimal.Decimal, picture string) string {
	// split picture at dot
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	intPlaceCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaceCount++
		}
	}
	// obtain absolute value
	abs := val.Abs()
	// scaled integer for extracting digits
	scaled := abs.Shift(int32(fracDigits)).Truncate(0)
	// Use integer arithmetic via decimal to string
	// integer part = scaled / 10^fracDigits
	tenFrac := pow10Dec(fracDigits)
	intPartDec := scaled.Div(tenFrac).Truncate(0)
	fracPartDec := scaled.Mod(tenFrac)

	// integer part low-order truncation to intPlaceCount digits
	var intPartInt int64
	if intPlaceCount > 0 {
		modInt := pow10Dec(intPlaceCount)
		intPartDec = intPartDec.Mod(modInt)
		intPartInt = intPartDec.IntPart()
	} else {
		intPartInt = 0
	}
	fracPartInt := fracPartDec.IntPart()
	if fracPartInt < 0 {
		fracPartInt = -fracPartInt
	}

	intStr := fmt.Sprintf("%0*d", intPlaceCount, intPartInt)
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPartInt)
	}

	// map digit placeholders to their characters and suppression info
	// Build slices for integer part placeholders in order
	type place struct {
		picChar rune // Z or 9
		digit   byte // '0'..'9'
		space   bool // suppressed -> display as space
	}
	var intPlaces []place
	for i, ch := range intStr {
		// we need picChar for each placeholder in order of appearance in intPic
		_ = i
		_ = ch
		break
	}
	// collect picChars for integer part in order
	var intPicChars []rune
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPicChars = append(intPicChars, c)
		}
	}
	// build intPlaces aligned with intStr
	intPlaces = make([]place, intPlaceCount)
	for i := 0; i < intPlaceCount; i++ {
		intPlaces[i] = place{picChar: intPicChars[i], digit: intStr[i]}
	}

	// determine suppression: leading Z zeros become space
	suppressing := true
	for i := 0; i < intPlaceCount; i++ {
		d := intPlaces[i].digit
		pc := intPlaces[i].picChar
		if suppressing {
			if d != '0' {
				suppressing = false
			} else {
				if pc == '9' {
					suppressing = false
					// keep zero
				} else {
					intPlaces[i].space = true
				}
			}
		}
	}

	// Now build output string of length len(picture)
	// We need to know for each comma whether it should be blanked
	// A comma is blanked if all digit placeholders to its left are spaces (suppressed)
	// Determine prefix suppressed status
	// Precompute for each position in picture whether all int placeholders to left are spaces
	out := make([]rune, 0, len(picture))
	intPlaceIdx := 0
	fracPlaceIdx := 0

	// For comma suppression we need helper: is there any non-space digit placeholder left of comma?
	// We'll scan picture left to right and keep track
	// We already know which intPlaces are spaces

	for _, c := range picture {
		switch c {
		case 'Z', '9':
			// integer or fractional part? Need to know if we are before or after dot
			// Use flag: if dot exists, chars before dot are int, after dot are frac
			// But our loop over picture includes dot, so we can decide by position relative to dot
			// Instead we split handling: iterate over picture runes with index
			// We'll handle with separate loops for clarity
			out = append(out, '?') // placeholder, will fill later
		case ',', '.':
			out = append(out, c)
		default:
			out = append(out, c)
		}
	}
	// Now fill digit positions in order they appear in picture
	// Walk picture again
	pi := 0 // index into intPlaces
	fi := 0
	for idx, pc := range picture {
		if pc == 'Z' || pc == '9' {
			// determine if this placeholder belongs to int part or frac part
			// by checking position relative to dot
			isFrac := false
			if dotIdx >= 0 && idx > dotIdx {
				isFrac = true
			}
			if isFrac {
				var ch byte
				if fi < len(fracStr) {
					ch = fracStr[fi]
					fi++
				} else {
					ch = '0'
				}
				out[idx] = rune(ch)
			} else {
				pl := intPlaces[pi]
				pi++
				if pl.space {
					out[idx] = ' '
				} else {
					out[idx] = rune(pl.digit)
				}
			}
		}
	}
	// Handle commas: if all int placeholders to the left are spaces, comma becomes space
	for idx, pc := range picture {
		if pc == ',' {
			// look at all int placeholders that appear before this comma in picture
			// count how many int placeholders before idx are non-space
			hasNonSpace := false
			// Need to map placeholder positions to picture indices
			// Walk picture up to idx
			intIdx := 0
			for j := 0; j < idx; j++ {
				if picture[j] == 'Z' || picture[j] == '9' {
					// is it int part? j < dotIdx
					if dotIdx < 0 || j < dotIdx {
						if intIdx < len(intPlaces) && !intPlaces[intIdx].space {
							hasNonSpace = true
							break
						}
						intIdx++
					}
				}
			}
			if !hasNonSpace {
				out[idx] = ' '
			}
		}
	}
	// unused vars cleanup
	_ = intPlaceIdx
	_ = fracPlaceIdx
	return string(out)
}

func formatPrice(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatTotal(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZZ,ZZ9.99")
}

// file handling
var discFileLines []string
var discFileIdx int

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseDiscRec(line string) {
	// line is padded to 15
	if len(line) < 15 {
		line = padRight(line, 15)
	} else if len(line) > 15 {
		line = line[:15]
	}
	drItem := line[0:6]
	priceStr := strings.TrimSpace(line[6:13])
	var price decimal.Decimal
	if priceStr == "" {
		price = decimal.NewFromInt(0)
	} else {
		// priceStr contains digits only
		// remove any non-digit just in case
		clean := ""
		for _, c := range priceStr {
			if c >= '0' && c <= '9' {
				clean += string(c)
			}
		}
		if clean == "" {
			price = decimal.NewFromInt(0)
		} else {
			var iv int64
			fmt.Sscan(clean, &iv)
			// alternative parse with decimal
			d, _ := decimal.NewFromString(clean)
			price = d.Shift(-2)
			_ = iv
		}
	}
	pctStr := strings.TrimSpace(line[13:15])
	var pct int64 = 0
	if pctStr != "" {
		fmt.Sscan(pctStr, &pct)
	}
	discRec.DrItem = drItem
	discRec.DrPrice = price
	discRec.DrPct = pct
}

// paragraphs
func READPARA() {
	if discFileIdx >= len(discFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := discFileLines[discFileIdx]
	discFileIdx++
	// COBOL LINE SEQUENTIAL: pad with spaces if shorter than record length
	if len(line) < 15 {
		line = padRight(line, 15)
	}
	parseDiscRec(line)
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	// divide by 100 via Shift(-2)
	quot := prod.Shift(-2)
	rounded := quot.Round(2)
	WsDiscount = storePic(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netComp := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storePic(netComp, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	added := WsTotalNet.Add(WsNet)
	WsTotalNet = storePic(added, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = storeInt3(WsCount + 1)

	WsPriceEd = formatPrice(discRec.DrPrice)
	WsDiscEd = formatPrice(WsDiscount)
	WsNetEd = formatPrice(WsNet)

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-PCT prints zero-padded to 2 digits
	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	// DR-ITEM is exactly 6 chars as stored (including trailing spaces)
	// When DISPLAY concatenates, it uses the field's content as is (6 chars)
	lineOut := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(lineOut)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatTotal(WsTotalNet)
	// WS-COUNT prints zero-padded to 3 digits
	countStr := fmt.Sprintf("%03d", WsCount)
	lineOut := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Println(lineOut)
}

func main() {
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		discFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// extend buffer for long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			// Scanner strips newline and also strips carriage return?
			// Need to keep line as is (without newline)
			t := scanner.Text()
			// Scanner removed trailing \r for Windows lines? It handles \r\n -> Text() without \r
			discFileLines = append(discFileLines, t)
		}
		f.Close()
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	WsEofFlag = "N"
	discFileIdx = 0
	// PERFORM READ-PARA
	READPARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	// CLOSE already done
	SUMMARYPARA()
}

