		intPartInt = intPartDec.IntPart()
	} else {
		intPartInt = 0
	}
	fracPartInt := fracPartDec.IntPart()
	if fracPartInt < 0 {
		fracPartInt = -fracPartInt
	}

	intStr := fmt.Sprintf("%0*d", intPlaceCount, intPartInt)
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPartInt)
	}

	type place struct {
		picChar rune
		digit   byte
		space   bool
	}
	var intPlaces []place
	var intPicChars []rune
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPicChars = append(intPicChars, c)
		}
	}
	intPlaces = make([]place, intPlaceCount)
	for i := 0; i < intPlaceCount; i++ {
		intPlaces[i] = place{picChar: intPicChars[i], digit: intStr[i]}
	}

	suppressing := true
	for i := 0; i < intPlaceCount; i++ {
		d := intPlaces[i].digit
		pc := intPlaces[i].picChar
		if suppressing {
			if d != '0' {
				suppressing = false
			} else {
				if pc == '9' {
					suppressing = false
				} else {
					intPlaces[i].space = true
				}
			}
		}
	}

	out := make([]rune, 0, len(picture))
	for _, c := range picture {
		switch c {
		case 'Z', '9':
			out = append(out, '?')
		case ',', '.':
			out = append(out, c)
		default:
			out = append(out, c)
		}
	}
	pi := 0
	fi := 0
	for idx, pc := range picture {
		if pc == 'Z' || pc == '9' {
			isFrac := false
			if dotIdx >= 0 && idx > dotIdx {
				isFrac = true
			}
			if isFrac {
				var ch byte
				if fi < len(fracStr) {
					ch = fracStr[fi]
					fi++
				} else {
					ch = '0'
				}
				out[idx] = rune(ch)
			} else {
				pl := intPlaces[pi]
				pi++
				if pl.space {
					out[idx] = ' '
				} else {
					out[idx] = rune(pl.digit)
				}
			}
		}
	}
	for idx, pc := range picture {
		if pc == ',' {
			hasNonSpace := false
			intIdx := 0
			for j := 0; j < idx; j++ {
				if picture[j] == 'Z' || picture[j] == '9' {
					if dotIdx < 0 || j < dotIdx {
						if intIdx < len(intPlaces) && !intPlaces[intIdx].space {
							hasNonSpace = true
							break
						}
						intIdx++
					}
				}
			}
			if !hasNonSpace {
				out[idx] = ' '
			}
		}
	}
	return string(out)
}

func formatPrice(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatTotal(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZZ,ZZ9.99")
}

var discFileLines []string
var discFileIdx int

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseDiscRec(line string) {
	if len(line) < 15 {
		line = padRight(line, 15)
	} else if len(line) > 15 {
		line = line[:15]
	}
	drItem := line[0:6]
	priceStr := strings.TrimSpace(line[6:13])
	var price decimal.Decimal
	if priceStr == "" {
		price = decimal.NewFromInt(0)
	} else {
		clean := ""
		for _, c := range priceStr {
			if c >= '0' && c <= '9' {
				clean += string(c)
			}
		}
		if clean == "" {
			price = decimal.NewFromInt(0)
		} else {
			d, _ := decimal.NewFromString(clean)
			price = d.Shift(-2)
		}
	}
	pctStr := strings.TrimSpace(line[13:15])
	var pct int64 = 0
	if pctStr != "" {
		if v, err := strconv.ParseInt(pctStr, 10, 64); err == nil {
			pct = v
		} else {
			// fallback: extract digits only
			clean := ""
			for _, c := range pctStr {
				if c >= '0' && c <= '9' {
					clean += string(c)
				}
			}
			if clean != "" {
				if v2, err2 := strconv.ParseInt(clean, 10, 64); err2 == nil {
					pct = v2
				}
			}
		}
	}
	discRec.DrItem = drItem
	discRec.DrPrice = price
	discRec.DrPct = pct
}

func READPARA() {
	if discFileIdx >= len(discFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := discFileLines[discFileIdx]
	discFileIdx++
	if len(line) < 15 {
		line = padRight(line, 15)
	}
	parseDiscRec(line)
}

func PROCESSPARA() {
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	quot := prod.Shift(-2)
	rounded := quot.Round(2)
	WsDiscount = storePic(rounded, 5, 2)

	netComp := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storePic(netComp, 5, 2)

	added := WsTotalNet.Add(WsNet)
	WsTotalNet = storePic(added, 8, 2)

	WsCount = storeInt3(WsCount + 1)

	WsPriceEd = formatPrice(discRec.DrPrice)
	WsDiscEd = formatPrice(WsDiscount)
	WsNetEd = formatPrice(WsNet)

	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	lineOut := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(lineOut)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatTotal(WsTotalNet)
	countStr := fmt.Sprintf("%03d", WsCount)
	lineOut := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Println(lineOut)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		discFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			t := scanner.Text()
			discFileLines = append(discFileLines, t)
		}
		f.Close()
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	WsEofFlag = "N"
	discFileIdx = 0
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
